insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('zw', '/flags/history/zw-1924.svg', '1924-01-01', '1964-04-11', 'Rhodésie du Sud', 'Southern Rhodesia', 'Colonie autonome de la Couronne, la Rhodésie du Sud arbore un Blue Ensign chargé de ses armes, surmontées de l''oiseau de pierre du Grand Zimbabwe.', 'A self-governing Crown colony, Southern Rhodesia flew a Blue Ensign bearing its arms, topped by the stone bird of Great Zimbabwe.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('zw', '/flags/history/zw-1953.svg', '1953-08-01', '1963-12-31', 'Fédération de Rhodésie et du Nyassaland', 'Federation of Rhodesia and Nyasaland', 'Fédération des deux Rhodésies et du Nyassaland, dominée par la minorité blanche et dissoute fin 1963.', 'A federation of the two Rhodesias and Nyasaland, dominated by the white minority and dissolved at the end of 1963.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('zw', '/flags/history/zw-1964.svg', '1964-04-11', '1968-11-11', 'Rhodésie (1964-1968)', 'Rhodesia (1964–1968)', 'Ce Blue Ensign bleu ciel accompagne la déclaration unilatérale d''indépendance proclamée en 1965 par le régime minoritaire blanc de Ian Smith.', 'This light-blue Blue Ensign accompanied the unilateral declaration of independence proclaimed in 1965 by Ian Smith''s white-minority regime.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('zw', '/flags/history/zw-1968.png', '1968-11-11', '1979-06-01', 'Rhodésie (1968-1979)', 'Rhodesia (1968–1979)', 'Le régime de Ian Smith adopte un drapeau vert-blanc-vert aux armes, qu''aucun État ne reconnaît.', 'Ian Smith''s regime adopted a green-white-green flag with the arms, which no state recognised.');
